attributes.pql:
REMAP_VALUES(
  TO_STRING(
    FLOOR(
      SQRT(
        (
          PU_SUM(
            "o_celonis_MaterialMasterPlant"
            ,SQUARE(
              BIND(
                "o_celonis_MaterialMovement"
                ,PU_SUM(
                    DOMAIN_TABLE("o_celonis_MaterialMovement"."MaterialMasterPlant_ID")
                    ,"o_celonis_MaterialMovement"."MovementQuantityConverted"
                    ,"o_celonis_MaterialMovement"."IsConsumptionRelevant" = 'Relevant' AND
                    "o_celonis_MaterialMovement"."MovementDirection" = 'Outgoing' AND
                    "o_celonis_MaterialMovement"."MonthsSinceCreationTime" BETWEEN 1 AND ${im_consideredpastmonths}
                  )
                /
                ${im_consideredpastmonths}
                - 
                PU_SUM(
                  DOMAIN_TABLE(
                    "o_celonis_MaterialMovement"."MaterialMasterPlant_ID"
                    ,ROUND_MONTH("o_celonis_MaterialMovement"."CreationTime")
                  )
                  ,"o_celonis_MaterialMovement"."MovementQuantityConverted"
                  ,"o_celonis_MaterialMovement"."IsConsumptionRelevant" = 'Relevant' AND
                  "o_celonis_MaterialMovement"."MovementDirection" = 'Outgoing' AND
                  "o_celonis_MaterialMovement"."MonthsSinceCreationTime" BETWEEN 1 AND ${im_consideredpastmonths}
                ) 
              )
            )
            ,"o_celonis_MaterialMovement"."IsConsumptionRelevant" = 'Relevant' AND
            INDEX_ORDER ( 
              "o_celonis_MaterialMovement"."MaterialMasterPlant_ID"
              , ORDER BY (ROUND_MONTH("o_celonis_MaterialMovement"."CreationTime")) 
              , PARTITION BY (
                "o_celonis_MaterialMovement"."MaterialMasterPlant_ID"
                ,ROUND_MONTH("o_celonis_MaterialMovement"."CreationTime")
              ) 
            ) = 1 AND
            "o_celonis_MaterialMovement"."MonthsSinceCreationTime" BETWEEN 1 AND ${im_consideredpastmonths}
          )
          +
          PU_FIRST(
            "o_celonis_MaterialMasterPlant"
            ,(
              ${im_consideredpastmonths}
              -
              PU_COUNT_DISTINCT(
                DOMAIN_TABLE("o_celonis_MaterialMovement"."MaterialMasterPlant_ID")
                ,ROUND_MONTH("o_celonis_MaterialMovement"."CreationTime")
                ,"o_celonis_MaterialMovement"."IsConsumptionRelevant" = 'Relevant' AND
                "o_celonis_MaterialMovement"."MovementDirection" = 'Outgoing' AND
                "o_celonis_MaterialMovement"."MonthsSinceCreationTime" BETWEEN 1 AND ${im_consideredpastmonths}
              )
            )
            *
            SQUARE(
              BIND(
                "o_celonis_MaterialMovement"
                ,
                PU_SUM(
                    DOMAIN_TABLE("o_celonis_MaterialMovement"."MaterialMasterPlant_ID")
                    ,"o_celonis_MaterialMovement"."MovementQuantityConverted"
                    ,"o_celonis_MaterialMovement"."IsConsumptionRelevant" = 'Relevant' AND
                    "o_celonis_MaterialMovement"."MovementDirection" = 'Outgoing' AND
                    "o_celonis_MaterialMovement"."MonthsSinceCreationTime" BETWEEN 1 AND ${im_consideredpastmonths}
                  )
                /
                ${im_consideredpastmonths}
              )
            )
            ,"o_celonis_MaterialMovement"."IsConsumptionRelevant" = 'Relevant' AND
            "o_celonis_MaterialMovement"."MovementDirection" = 'Outgoing' AND
            "o_celonis_MaterialMovement"."MonthsSinceCreationTime" BETWEEN 1 AND ${im_consideredpastmonths}
          )
        )
        /
        ${im_consideredpastmonths}
      )
      /
      ABS(
        PU_SUM(
          "o_celonis_MaterialMasterPlant"
          ,"o_celonis_MaterialMovement"."MovementQuantityConverted"
          ,"o_celonis_MaterialMovement"."IsConsumptionRelevant" = 'Relevant' AND
          "o_celonis_MaterialMovement"."MovementDirection" = 'Outgoing' AND
          "o_celonis_MaterialMovement"."MonthsSinceCreationTime" BETWEEN 1 AND ${im_consideredpastmonths}
        )
        /${im_consideredpastmonths}
      )
    )
  )
  ,[NULL, NULL], ['0', 'X'], ['1', 'Y'], 'Z'
)
